// Parse the PayPlus payload forwarded by the site
const body = $input.first().json.body || $input.first().json;
const d = body.data || body;
const t = d.transaction || d.data || d;

const email  = t.customer_email || t.email || d.customer_email || '';
const name   = t.customer_name || t.full_name || d.customer_name || 'לקוח/ה יקר/ה';
const amount = t.amount || d.amount || '';
const currency = t.currency_code || d.currency || 'ILS';
const info   = t.more_info || d.more_info || 'חבילת SkiShare';
const ref    = t.transaction_uid || t.uid || d.page_request_uid || '';

const html = `
<div dir="rtl" style="font-family:Arial,Helvetica,sans-serif;max-width:600px;margin:auto;background:#f7f9fb;padding:0">
  <div style="background:#0b1f3a;padding:28px;text-align:center">
    <div style="color:#fff;font-size:26px;font-weight:800">SkiShare</div>
    <div style="color:#9fb3d1;font-size:13px;margin-top:4px">Val Thorens · France</div>
  </div>
  <div style="background:#fff;padding:28px;color:#1f2937">
    <h1 style="font-size:22px;margin:0 0 6px">היי ${name}, קיבלנו את ההזמנה! 🎿</h1>
    <p style="color:#6b7280;font-size:14px;line-height:1.6;margin:0 0 20px">תודה שבחרת ב-SkiShare. להלן פרטי ההזמנה. נציג שלנו יאשר אותה סופית ויצור קשר.</p>
    <table style="width:100%;border-collapse:collapse;font-size:14px">
      <tr><td style="padding:10px 0;color:#6b7280">חבילה</td><td style="padding:10px 0;font-weight:700;text-align:left">${info}</td></tr>
      <tr><td style="padding:10px 0;color:#6b7280;border-top:1px solid #eef2f7">סכום</td><td style="padding:10px 0;font-weight:700;text-align:left;border-top:1px solid #eef2f7">${amount} ${currency}</td></tr>
      <tr><td style="padding:10px 0;color:#6b7280;border-top:1px solid #eef2f7">אסמכתא</td><td style="padding:10px 0;text-align:left;border-top:1px solid #eef2f7">${ref}</td></tr>
    </table>
    <div style="background:#eff6ff;border:1px solid #dbeafe;border-radius:12px;padding:14px;margin-top:20px;font-size:13px;color:#1e3a8a">הסכום נשמר כפיקדון. החיוב בפועל יבוצע רק לאחר אישור ההזמנה ע״י נציג SkiShare.</div>
    <p style="color:#9ca3af;font-size:12px;margin-top:24px">שאלות? וואטסאפ 054-7701899 · skishareteam@gmail.com</p>
  </div>
  <div style="text-align:center;color:#9ca3af;font-size:11px;padding:16px">© SkiShare · סקי שר בע״מ · הזוהר 12, קיסריה</div>
</div>`;

return [{ json: { to: email, subject: 'אישור הזמנה — SkiShare 🎿', html, name, amount, currency, info, ref } }];
